# ---------------------------------------------------------------------------- Excel
def build_xlsx(path):
    from openpyxl.chart import BarChart, LineChart, Reference
    from xlsxkit import Book, instructions, walkthrough, card_sheet
    ch = CH
    b = Book()
    instructions(b, ch, [
        "شرح_الحالة: اقرأها أولا؛ تشرح الحالة وأرقامها وكيفية قراءة النتائج خطوة بخطوة.",
        "تمرين_1: بيانات الانسحاب، والرسم الأصلي والمعاد تصميمه، والأثر المالي، وصياغة الفكرة الكبرى.",
        "تمرين_2: اختيار الرسم المناسب لثماني رسائل.",
        "تمرين_3: اكتب بطاقة إيصال القرار لقرار من مجالك وقيّمها بخمسة معايير.",
        "الإجابات: للمدرس فقط، أخفِها قبل التوزيع.",
    ])
    walkthrough(b, ch, [
        ("الحالة", ["شركة اتصالات لديها ثلاث شرائح: الدفع المسبق (400 ألف عميل)، والآجل، والأعمال. معدل الانسحاب الربعي لكل شريحة في أربعة أرباع مسجل في تمرين_1.",
                    "المطلوب: أن تحوّل الجدول إلى رسالة واحدة وأثر مالي، وأن تعيد تصميم الرسم ليحمل الرسالة، ثم تصوغ الفكرة الكبرى للعرض على المدير التجاري."]),
        ("المصطلحات", ["الفكرة الكبرى: جملة واحدة تحمل الموقف وما المعرّض للخطر والمطلوب.",
                       "التغير النسبي: (القيمة الأخيرة ÷ الأولى) − 1.",
                       "الأثر المالي: عدد العملاء × فرق معدل الانسحاب × متوسط الإيراد الشهري × 12.",
                       "العنوان الرسالي: عنوان يقول ما يجب أن يُرى، لا اسم المتغيرات."]),
        ("ما تفعله في ورقة تمرين_1", ["الخطوة 1: اقرأ الجدول، ثم الرسم الأصلي (أعمدة متلاصقة ملونة): أين تنظر العين أولا؟",
                                     "الخطوة 2: اقرأ الرسم المعاد تصميمه (خطوط، الدفع المسبق بلون بارز والباقي رمادي).",
                                     "الخطوة 3: الصيغ تحسب التغير (+61% للدفع المسبق) والعملاء الإضافيين كل ربع (7,600) والأثر السنوي (نحو 4.1 مليون ريال).",
                                     "الخطوة 4: اكتب عناصر الفكرة الكبرى في الخلايا الصفراء، وتابع الجملة المكونة منها، ثم احكم عليها بالمعايير.",
                                     "جرّب: غيّر معدل الربع الرابع للدفع المسبق إلى 4.0% وتابع الأثر المالي."]),
        ("ما تفعله في ورقة تمرين_2", ["لكل رسالة اختر من القائمة الرسم المناسب. تظهر «مناسب» أو «راجع اختيارك» بعد الاختيار، وعدد المناسب في الأسفل."]),
        ("ما تفعله في ورقة تمرين_3", ["اكتب بطاقة إيصال القرار لقرار من مجالك، ثم قيّم نفسك بالمعايير الخمسة: صفر، واحد، اثنان."]),
        ("أخطاء شائعة", ["عرض كل الرسوم بترتيب صنعها.", "عنوان يسمي المتغيرات ولا يقول الرسالة.",
                         "تلوين كل السلاسل بألوان زاهية فلا يتميز شيء.", "رقم مفرد بلا هامش.", "عرض بلا طلب في النهاية."]),
        ("سؤال للتحقق من فهمك", ["لو كان معدل الربع الرابع للدفع المسبق 4.0% بدل 5.0%، فكم يكون الأثر السنوي؟",
                                 "الجواب: 400,000 × 0.9% = 3,600 عميل كل ربع؛ × 45 × 12 ≈ 1.94 مليون ريال."]),
    ])

    s = b.sheet("تمرين_1", (30, 14, 14, 14, 14, 14))
    s.title("من الجدول إلى الرسالة: انسحاب العملاء الربعي", span=6)
    s.header(["الشريحة", "الربع الأول", "الربع الثاني", "الربع الثالث", "الربع الرابع", "التغير"])
    first = s.row
    for name, vals in [("الدفع المسبق", [0.031, 0.034, 0.042, 0.050]), ("الآجل", [0.012, 0.011, 0.013, 0.012]), ("الأعمال", [0.008, 0.009, 0.008, 0.009])]:
        r = s.line([name] + vals + [None], ["label"] + ["input"] * 4 + ["formula"], [None] + ["0.0%"] * 4 + [None])
        s.put(r, 6, f"=E{r}/B{r}-1", "formula", "+0%;-0%")
    last = s.row - 1
    s.skip()
    r_n = s.line(["عدد عملاء الدفع المسبق", 400000], ["label", "input"], [None, "#,##0"])
    r_a = s.line(["متوسط الإيراد الشهري للعميل (ريال)", 45], ["label", "input"])
    r_x = s.line(["عملاء إضافيون يغادرون كل ربع", f"=B{r_n}*(E{first}-B{first})"], ["label", "formula"], [None, "#,##0"])
    r_y = s.line(["الإيراد السنوي المفقود لكل دفعة ربعية (ريال)", f"=B{r_x}*B{r_a}*12"], ["label", "formula"], [None, "#,##0"])
    s.skip()
    s.section("صياغة الفكرة الكبرى", span=6)
    r1 = s.line(["ماذا تغيّر؟ (الموقف)", "ارتفع انسحاب عملاء الدفع المسبق 61% خلال عام"], ["label", "input"])
    r2 = s.line(["ما المعرّض للخطر؟", "ويُفقدنا نحو 4.1 مليون ريال من الإيراد السنوي عن كل ربع"], ["label", "input"])
    r3 = s.line(["ما المطلوب؟", "نوصي باعتماد تجربة عرض استبقاء بمليوني ريال في منطقتين"], ["label", "input"])
    for r in (r1, r2, r3):
        s.ws.merge_cells(start_row=r, start_column=2, end_row=r, end_column=6)
    r4 = s.line(["الفكرة الكبرى", f'=B{r1}&"، "&B{r2}&"؛ "&B{r3}&"."'], ["label", "formula"], height=40)
    s.ws.merge_cells(start_row=r4, start_column=2, end_row=r4, end_column=6)
    r5 = s.line(["عدد الكلمات", f'=LEN(TRIM(B{r4}))-LEN(SUBSTITUTE(TRIM(B{r4})," ",""))+1'], ["label", "formula"])
    s.line(["حكمك: هل تحمل الجملة موقفا وأثرا ومطلوبا؟", ""], ["label", "input"])
    s.dropdown(f"B{s.row - 1}", ["نعم كاملة", "ينقصها الأثر", "ينقصها المطلوب", "عنوان لا فكرة"])
    s.note("جرّب: اجعل معدل الربع الرابع للدفع المسبق 4.0% وتابع الأثر المالي، ثم عدّل جملة الأثر.", span=6)

    cats = Reference(s.ws, min_col=2, max_col=5, min_row=first - 1)
    bar = BarChart()
    bar.type = "col"
    bar.title = "معدل الانسحاب بحسب الشريحة (الرسم الأصلي)"
    bar.add_data(Reference(s.ws, min_col=1, max_col=5, min_row=first, max_row=last), from_rows=True, titles_from_data=True)
    bar.set_categories(cats)
    bar.height, bar.width = 7, 13
    s.ws.add_chart(bar, "H2")
    line = LineChart()
    line.title = "انسحاب الدفع المسبق ارتفع من 3.1% إلى 5.0%، والشرائح الأخرى مستقرة"
    line.add_data(Reference(s.ws, min_col=1, max_col=5, min_row=first, max_row=last), from_rows=True, titles_from_data=True)
    line.set_categories(cats)
    for i, ser in enumerate(line.series):
        color = "B5532A" if i == 0 else "B0B8BA"
        ser.graphicalProperties.line.solidFill = color
        ser.graphicalProperties.line.width = 38000 if i == 0 else 19000
        ser.smooth = False
    line.y_axis.majorGridlines = None
    line.y_axis.number_format = "0.0%"
    line.height, line.width = 7, 13
    s.ws.add_chart(line, "H18")

    s2 = b.sheet("تمرين_2", (58, 26, 18))
    s2.title("اختر الرسم المناسب لكل رسالة", span=3)
    options = ["نص كبير", "أعمدة أفقية مرتبة", "خط", "انتشار", "رسم الميل", "جدول"]
    s2.header(["الرسالة", "اختيارك", "النتيجة"])
    items = [("رقم رئيس واحد: نسبة الرضا 92%", "نص كبير"),
             ("مقارنة مبيعات سبع مناطق هذا العام", "أعمدة أفقية مرتبة"),
             ("تطور زمن الاستجابة شهريا لعامين", "خط"),
             ("العلاقة بين الخصم وحجم الطلب لـ200 عميل", "انتشار"),
             ("تغير ترتيب خمسة منتجات بين عامين", "رسم الميل"),
             ("أسعار 12 صنفا يرجع إليها فريق المبيعات", "جدول"),
             ("حصة ثلاث قنوات بيع خلال ثمانية أرباع", "خط"),
             ("أداء عشرة فروع مرتبة من الأعلى للأدنى", "أعمدة أفقية مرتبة")]
    ans = b.sheet("الإجابات", (58, 26))
    ans.title("الإجابات النموذجية (للمدرس)", span=2)
    ans.header(["الرسالة", "الرسم المناسب"])
    a_first = ans.row
    for msg, correct in items:
        ans.line([msg, correct])
    f0 = s2.row
    for k, (msg, correct) in enumerate(items):
        r = s2.line([msg, "", None], ["label", "input", "formula"])
        s2.put(r, 3, f'=IF(B{r}="","",IF(B{r}=الإجابات!B{a_first + k},"مناسب","راجع اختيارك"))', "formula")
        s2.dropdown(f"B{r}", options)
    r = s2.line(["عدد الاختيارات المناسبة", None, f'=COUNTIF(C{f0}:C{s2.row - 1},"مناسب")'], ["label", None, "formula"])
    s2.note("بعض الرسائل تحتمل أكثر من شكل؛ المهم أن تعلل اختيارك بالرسالة لا بالبيانات.", span=3)

    card_sheet(b, "تمرين_3", "بطاقة إيصال القرار: قرار في مجالك",
               ["الجمهور: من، وما يعرف، وما يهمه", "الفكرة الكبرى", "الافتتاحية: الموقف والتعقيد والسؤال والإجابة",
                "الرسائل الثلاث", "الرسم المناسب لكل رسالة وسبب اختياره", "عدم اليقين وما يغيّر القرار",
                "المطلوب: القرار والموعد والمسؤول", "الأسئلة المتوقعة وأجوبتها"],
               ["الفكرة الكبرى", "الجمهور", "الرسوم", "عدم اليقين", "المطلوب"])
